# GENERATED by builder application candidate; unit tests, not native PostgreSQL proof.
"""Wrapper behavior only. Real grants/locks/rollback require owner integration tests."""
from contextlib import contextmanager
from pathlib import Path
import sys
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parent))
from owned_migration import MigrationError, MigrationPolicy, migration_transaction

P = MigrationPolicy('sample', 'sample_migrator', 'sample_runtime', 'sample_operator')


class Rows:
    def __init__(self, values): self.values = values
    def mappings(self): return self
    def all(self): return self.values


class Connection:
    def __init__(self):
        self.statements = []
        self.identity = dict(current=P.migrator, session=P.migrator, database_owner='fixture_admin',
                             superuser=False, bypassrls=False, createdb=False, createrole=False, replication=False)
        self.schema = [{'owner': P.migrator}]
        self.lock_error = None

    def execute(self, statement, parameters=None):
        value = str(statement)
        self.statements.append((value, parameters))
        if '/* identity */' in value: return Rows([self.identity])
        if '/* schema */' in value: return Rows(self.schema)
        if 'pg_advisory_xact_lock' in value:
            if self.lock_error: raise self.lock_error
            return Rows([])
        if value.startswith('SET LOCAL '): return Rows([])
        raise AssertionError('unexpected_query')


class Engine:
    def __init__(self):
        self.connection = Connection()
        self.entered = self.committed = self.rolled_back = False

    @contextmanager
    def begin(self):
        self.entered = True
        try: yield self.connection
        except BaseException:
            self.rolled_back = True
            raise
        else: self.committed = True


class MigrationTests(unittest.TestCase):
    def test_existing_owner_tables_can_receive_the_next_migration(self):
        engine = Engine()
        # Existing application objects/history are intentionally not inventoried by
        # the wrapper. These values document the acceptance scenario, not DB evidence.
        engine.connection.tables = ['alembic_version', 'capture']
        engine.connection.history = ['0002_capture']
        effects = []
        with migration_transaction(engine, P) as connection:
            effects.append('next_migration')
            connection.history = ['0003_next']
        self.assertEqual(effects, ['next_migration'])
        self.assertTrue(engine.committed)

    def test_wrong_role_never_receives_migration_connection(self):
        for current, session in [(P.runtime, P.runtime), (P.operator, P.operator), (P.migrator, 'administrator')]:
            engine = Engine()
            engine.connection.identity.update(current=current, session=session)
            with self.assertRaisesRegex(MigrationError, '^owned_migration_authority_invalid$'):
                with migration_transaction(engine, P): self.fail('migration effect')
            self.assertTrue(engine.rolled_back)
            self.assertFalse(engine.committed)

    def test_administrator_flags_or_database_ownership_refuse(self):
        for flag in ['superuser', 'bypassrls', 'createdb', 'createrole', 'replication']:
            engine = Engine()
            engine.connection.identity[flag] = True
            with self.assertRaisesRegex(MigrationError, 'authority_invalid'):
                with migration_transaction(engine, P): self.fail('migration effect')
        for owner in [P.migrator, P.runtime, P.operator]:
            engine = Engine()
            engine.connection.identity['database_owner'] = owner
            with self.assertRaisesRegex(MigrationError, 'authority_invalid'):
                with migration_transaction(engine, P): self.fail('migration effect')

    def test_missing_or_foreign_schema_refuses_before_effects(self):
        for schema in [[], [{'owner': 'foreign_owner'}]]:
            engine = Engine()
            engine.connection.schema = schema
            with self.assertRaisesRegex(MigrationError, '^owned_migration_schema_invalid$'):
                with migration_transaction(engine, P): self.fail('migration effect')
            self.assertTrue(engine.rolled_back)
            self.assertFalse(engine.committed)

    def test_lock_and_timeouts_precede_migration_effects(self):
        engine = Engine()
        with migration_transaction(engine, P) as connection:
            statements = [s for s, _ in connection.statements]
            self.assertIn('pg_advisory_xact_lock', statements[-1])
            for setting in ['search_path', 'lock_timeout', 'statement_timeout', 'idle_in_transaction_session_timeout', 'transaction_timeout']:
                self.assertTrue(any(s.startswith('SET LOCAL ' + setting + '=') for s in statements))
        self.assertTrue(engine.committed)

    def test_lock_failure_never_yields_or_commits(self):
        engine = Engine()
        engine.connection.lock_error = TimeoutError('PRIVATE_CONNECTION_DETAILS')
        with self.assertRaisesRegex(MigrationError, '^owned_migration_failed_requires_reconciliation$') as caught:
            with migration_transaction(engine, P): self.fail('migration effect')
        self.assertTrue(engine.rolled_back)
        self.assertFalse(engine.committed)
        self.assertNotIn('PRIVATE', str(caught.exception))

    def test_same_owner_serializes_on_same_lock_other_owner_is_independent(self):
        keys = []
        for policy in [P, P, MigrationPolicy('other', P.migrator, P.runtime, P.operator)]:
            engine = Engine()
            with migration_transaction(engine, policy): pass
            keys.append(next(p['key'] for s, p in engine.connection.statements if 'pg_advisory_xact_lock' in s))
        self.assertEqual(keys[0], keys[1])
        self.assertNotEqual(keys[0], keys[2])

    def test_migration_failure_is_safe_and_never_commits(self):
        engine = Engine()
        with self.assertRaisesRegex(MigrationError, '^owned_migration_failed_requires_reconciliation$') as caught:
            with migration_transaction(engine, P): raise ValueError('PRIVATE_DATABASE_PASSWORD')
        self.assertTrue(engine.rolled_back)
        self.assertFalse(engine.committed)
        self.assertTrue(caught.exception.__suppress_context__)
        self.assertNotIn('PRIVATE', str(caught.exception))

    def test_existing_safe_failure_still_blocks_commit(self):
        engine = Engine()
        with self.assertRaisesRegex(MigrationError, '^owned_migration_schema_invalid$'):
            with migration_transaction(engine, P): raise MigrationError('owned_migration_schema_invalid')
        self.assertTrue(engine.rolled_back)
        self.assertFalse(engine.committed)

    def test_migration_error_cannot_render_private_messages_or_chained_causes(self):
        import traceback
        for code in ['owned_migration_schema_invalid', 'PRIVATE_DATABASE_PASSWORD']:
            for explicit in [False, True]:
                engine = Engine()
                with self.assertRaises(MigrationError) as caught:
                    with migration_transaction(engine, P):
                        try: raise ValueError('PRIVATE_DATABASE_PASSWORD')
                        except ValueError as cause:
                            if explicit: raise MigrationError(code) from cause
                            raise MigrationError(code)
                rendered = ''.join(traceback.format_exception(caught.exception))
                self.assertNotIn('PRIVATE', rendered)
                self.assertFalse(engine.committed)
                self.assertTrue(engine.rolled_back)

    def test_invalid_policy_rejected_without_opening_engine(self):
        for name in ['bad-schema', 'public;DROP', 'UPPER', '', None]:
            with self.assertRaisesRegex(MigrationError, 'policy_invalid'):
                MigrationPolicy(name, P.migrator, P.runtime, P.operator)
        with self.assertRaisesRegex(MigrationError, 'policy_invalid'):
            MigrationPolicy(P.schema, P.migrator, P.migrator, P.operator)
        engine = Engine()
        with self.assertRaisesRegex(MigrationError, 'policy_invalid'):
            with migration_transaction(engine, None): self.fail('effect')
        self.assertFalse(engine.entered)


if __name__ == '__main__': unittest.main()
